3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
10	
11	/**
12	 * The single duplicate check for the create-owner endpoint. It consolidates the former separate
13	 * telephone, email and household checks into one derived {@code identityKey}
14	 * ({@code normalizedTelephone|email|householdId}, see {@link OwnerIdentity}, also returned on the
15	 * owner) and rejects (409) when a new owner collides with an existing one on that identity.
16	 *
17	 * <p>The collision is driven by the normalized telephone (the leading, always-present component of
18	 * the key) together with the lower-cased email: two owners sharing both collide. Because the
19	 * telephone is part of the identity, two members of the same household (same {@code householdId})
20	 * with different telephones do <em>not</em> collide and are both allowed — a change from the former
21	 * household check, which rejected them regardless of telephone.
22	 *
23	 * <p>Runs after {@link ValidateOwnerFields} has normalized the telephone (E.164), email (lower-cased)
24	 * and address, and within the write transaction so the check and the insert see one consistent view.
25	 */
26	public class CheckIdentityUnique {
27	
28	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
29	            throws DuplicateIdentityException {
30	        String telephone = request.getTelephone();
31	        String email = normalizeEmail(request.getEmail());
32	        for (Owner existing : ownerRepository.findAll()) {
33	            boolean sameTelephone = telephone != null && telephone.equals(existing.getTelephone());
34	            boolean sameEmail = email.equals(normalizeEmail(existing.getEmail()));
35	            if (sameTelephone && sameEmail) {
36	                String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
37	                throw new DuplicateIdentityException(
38	                        OwnerIdentity.identityKey(telephone, request.getEmail(), householdId));
39	            }
40	        }
41	    }
42	
43	    /** Lower-cased email, or {@code ""} when absent/blank, so the comparison is case-insensitive. */
44	    private static String normalizeEmail(String email) {
45	        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
46	    }
47	}
